951	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
952	  let route: string;
953	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; }
954	  catch { respond(res, 400, { error: 'invalid request path' }); return; }
955	
956	  // /api/articles/:id (match the raw path first; decode only the captured id)
957	  const itemMatch = /^\/api\/articles\/([^/]+)$/.exec(route);
958	  let itemId: string | null = null;
959	  if (itemMatch) {
960	    try { itemId = decodeURIComponent(itemMatch[1]); }
961	    catch { respond(res, 400, { error: 'invalid article id encoding' }); return; }
