1023	    return;
1024	  }
1025	
1026	  // /api/articles
1027	  if (req.method === 'GET') {
1028	    respond(res, 200, { [RESOURCE]: readArticles() });
1029	    return;
1030	  }
1031	  if (req.method === 'POST') {
