2433	// 请求体大小限制的服务端回归保障（上限 5×1024×1024 字节）。
2434	// 上面的页面测试已覆盖“超长英文正文触发保存失败后保留输入”；这里固定服务端
2435	// 对“实际发送的整份 JSON 请求体 UTF-8 字节数”的判断本身：
2436	//   - 标题、摘要、正文、更新时的 version 与 JSON 结构全部计入；
2437	//   - 合法请求恰好达到上限成功，超出哪怕一个字节也拒绝；
2438	//   - 中文等多字节文字按字节而非字符计数，换行（JSON 中转义为 \n）同样计入；
2439	//   - 正文自身未超限、加上其他字段整份请求才超限，也算超限；
2440	//   - Content-Length 与分块传输遵守同一上限、同一结论；分块时前帧尚在限内、
2441	//     后帧才让累计字节超限，客户端仍能读到完整、可解析的 400 与非空 error，
2442	//     而不是连接中断或残缺响应，连接随后还能继续使用；
2443	//   - 拒绝新建不新增记录；拒绝更新不改动原文章任何字段，其他草稿不受影响；
2444	//   - 合法新建 201/版本1，合法更新 200/标识与创建时间不变/版本只加一，
2445	//     多语言与换行内容经现有 GET 读取入口原样取回，标题按规则去首尾空白。
2446	// 这些场景直接驱动 HTTP（原始 TCP 套接字精确控制线上字节与分块帧），持久化
2447	// 内容仍只通过现有读取入口核对，不改变首页编辑方式与已公开的保存行为。
2448	// ===========================================================================
2449	
2450	const MAX_BODY_BYTES = 5 * 1024 * 1024;
2451	
2452	// 以固定字段顺序构造与页面一致的负载（{title,summary,body}[,version]），
2453	// 把 padField 用 padUnit 重复填充（剩余字节用 ASCII 'a' 补齐），使整份 JSON
2454	// 请求体经 UTF-8 编码后恰好为 size 个字节。换行等需 JSON 转义的字符按其
2455	// 在线上 JSON 文本中的实际字节数计量。
2456	function buildPaddedObject(version, padField, pad) {
2457	  const obj = { title: 't', summary: 's', body: 'b' };
2458	  if (version !== null) obj.version = version; // version 始终位于 body 之后
2459	  obj[padField] = pad; // 更新已有键，不改变字段顺序
2460	  return obj;
2461	}
2462	
2463	function sizedObjectBody(size, { version = null, padField = 'body', padUnit = 'x' } = {}) {
2464	  const overhead = Buffer.byteLength(JSON.stringify(buildPaddedObject(version, padField, '')), 'utf8');
2465	  const unitWire = Buffer.byteLength(JSON.stringify(buildPaddedObject(version, padField, padUnit)), 'utf8') - overhead;
2466	  assert.ok(unitWire > 0);
2467	  const units = Math.floor((size - overhead) / unitWire);
2468	  let pad = padUnit.repeat(units);
2469	  let body = Buffer.from(JSON.stringify(buildPaddedObject(version, padField, pad)), 'utf8');
2470	  if (body.length < size) {
2471	    pad += 'a'.repeat(size - body.length); // 差额必小于 unitWire，1 字节 ASCII 可精确补齐
2472	    body = Buffer.from(JSON.stringify(buildPaddedObject(version, padField, pad)), 'utf8');
2473	  }
2474	  assert.equal(body.length, size, `无法精确拼出 ${size} 字节的请求体（实际 ${body.length}）`);
2475	  return body;
2476	}
2477	
2478	// 统一核对超限拒绝：完整可读的 400、非空且明确说明“超过允许大小”的 error。
2479	function assertTooLargeResponse(res, transport) {
2480	  assert.equal(res.status, 400, `${transport}：超过上限哪怕一个字节也必须是 400，实际 ${res.status}`);
2481	  assert.match(res.headers['content-type'] || '', /application\/json/, `${transport}：400 应为 JSON`);
2482	  const declared = res.headers['content-length'];
2483	  assert.notEqual(declared, undefined, `${transport}：400 必须带 Content-Length`);
2484	  assert.equal(res.body.length, Number(declared),
2485	    `${transport}：必须读到完整 400 响应体（${res.body.length}/${declared}），不能是连接中断或残缺响应`);
2486	  let data;
2487	  assert.doesNotThrow(() => { data = JSON.parse(res.body.toString('utf8')); },
2488	    `${transport}：400 响应体必须是可解析的 JSON`);
2489	  assert.ok(typeof data.error === 'string' && data.error.trim() !== '',
2490	    `${transport}：error 必须非空`);
2491	  assert.match(data.error, /allowed size|too large|exceed/i,
2492	    `${transport}：error 必须明确说明超过允许大小：${data.error}`);
2493	  return data.error;
2494	}
