1	// Launches the real server (node server.ts serve) on an ephemeral port with a
2	// throwaway data directory, exactly as documented in README. No test-only
3	// branches exist in the product; tests only talk HTTP/UI to it.
4	import { spawn } from 'node:child_process';
5	import { mkdtempSync, rmSync } from 'node:fs';
6	import { tmpdir } from 'node:os';
7	import { join, dirname } from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	import { setTimeout as sleep } from 'node:timers/promises';
10	
11	const here = dirname(fileURLToPath(import.meta.url));
12	export const SERVER_TS = process.env.QUILL_SERVER_TS || join(here, '..', 'server.ts');
13	
14	export class TestServer {
15	  constructor(process_, url, dataDir) {
16	    this.process = process_;
17	    this.url = url;
18	    this.dataDir = dataDir;
19	  }
20	
21	  static async start() {
22	    const dataDir = mkdtempSync(join(tmpdir(), 'quillpress-data-'));
23	    const child = spawn(process.execPath, [
24	      SERVER_TS, 'serve',
25	      '--host', '127.0.0.1',
26	      '--port', '0',
27	      '--data-dir', dataDir,
28	    ], { stdio: ['ignore', 'pipe', 'pipe'] });
29	
30	    let output = '';
31	    const url = await new Promise((resolve, reject) => {
32	      const onData = (chunk) => {
33	        output += chunk.toString();
34	        const match = /listening on (http:\/\/[^\s]+)/.exec(output);
35	        if (match) {
36	          child.stdout.off('data', onData);
37	          child.stderr.off('data', onData);
38	          resolve(match[1].replace(/\/$/, ''));
39	        }
40	      };
41	      child.stdout.on('data', onData);
42	      child.stderr.on('data', onData);
43	      child.on('error', reject);
44	      child.on('exit', (code) => {
45	        reject(new Error(`server exited early (${code}):\n${output}`));
46	      });
47	    });
48	
49	    // Wait for the port to actually accept connections.
50	    const deadline = Date.now() + 10000;
51	    for (;;) {
52	      try {
53	        const res = await fetch(`${url}/health`);
54	        if (res.ok) break;
55	      } catch { /* not ready yet */ }
56	      if (Date.now() > deadline) throw new Error('server did not become healthy');
57	      await sleep(25);
58	    }
59	    return new TestServer(child, url, dataDir);
60	  }
61	
62	  // Raw API access for verifying the persisted state behind the UI.
63	  api(path, options) {
64	    return fetch(`${this.url}${path}`, {
65	      ...options,
66	      headers: { 'content-type': 'application/json', accept: 'application/json', ...(options && options.headers) },
67	    });
68	  }
69	
70	  async listArticles() {
71	    const res = await this.api('/api/articles');
72	    if (!res.ok) throw new Error(`GET /api/articles -> ${res.status}`);
73	    return (await res.json()).articles;
74	  }
75	
76	  async stop() {
77	    if (this.process.exitCode === null) {
78	      this.process.kill('SIGTERM');
79	      await Promise.race([
80	        new Promise((resolve) => this.process.on('exit', resolve)),
81	        sleep(3000),
82	      ]);
83	    }
84	    if (this.process.exitCode === null) this.process.kill('SIGKILL');
85	    rmSync(this.dataDir, { recursive: true, force: true });
86	  }
87	}
88

